queries.statement_or_equivalent:
SELECT u.user_id FROM users u
        JOIN roles r ON r.role_id=u.role_id WHERE {'u.firebase_uid=:id' if uid is not None else 'u.user_id=:id'}
        AND u.is_active=TRUE AND r.role_name='coordinator'

